#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Lighting : 3
COMPONENT Layering : 1
COMPONENT Scripting : 1
COMPONENT KeyDeviceSensor : 1

NavigationInfo {
  headlight FALSE
}

Viewpoint {
  position 0 0 16
}

Group {
  children [
    DEF L1 DirectionalLight {
      color 1 0.2 0.2
      direction 1 0 -1
    }
    Transform {
      translation -3 2 0
      children Shape {
        appearance Appearance {
          material Material { }
        }
        geometry Sphere {
          radius 0.9
        }
      }
    }
  ]
}

Transform {
  translation 3 2 0
  children Shape {
    appearance Appearance {
      material Material { }
    }
    geometry Sphere {
      radius 0.9
    }
  }
}

Group {
  children [
    DEF L2 PointLight {
      color 0.2 1 0.2
      location 0 -2 3
    }
    Transform {
      translation -3 -2 0
      children Shape {
        appearance Appearance {
          material Material { }
        }
        geometry Sphere {
          radius 0.9
        }
      }
    }
  ]
}

Transform {
  translation 3 -2 0
  children Shape {
    appearance Appearance {
      material Material { }
    }
    geometry Sphere {
      radius 0.9
    }
  }
}

DEF K KeySensor { }

DEF R Script {
  inputOnly      SFString on_key
  initializeOnly SFNode   l1 USE L1
  initializeOnly SFNode   l2 USE L2

  url "javascript:
function on_key (k)
{
   if (k == 'g') l1 .global = true;
   if (k == 'h') l1 .global = false;
   if (k == 'p') l2 .global = false;
   if (k == 'o') l1 .on = false;
   if (k == 'n') l1 .on = true;
   if (k == 'i') l2 .intensity = 0.3;
}
"
  directOutput TRUE
}

ROUTE K.keyPress TO R.on_key

